BEGIN;
CREATE TABLE IF NOT EXISTS research.financial_segment_facts (id BIGSERIAL PRIMARY KEY,production_run_id BIGINT NOT NULL REFERENCES research.financial_production_runs(id) ON DELETE CASCADE,company_id BIGINT NOT NULL REFERENCES research.companies(id),fiscal_year INTEGER NOT NULL,period_end DATE NOT NULL,segment_type TEXT NOT NULL CHECK(segment_type IN ('business','geography','unallocated')),segment_key TEXT NOT NULL,segment_name TEXT NOT NULL,metric_key TEXT NOT NULL,value NUMERIC,currency TEXT NOT NULL DEFAULT 'INR',unit TEXT NOT NULL DEFAULT 'lakh',source_page INTEGER NOT NULL,reported_line TEXT NOT NULL,extraction_status TEXT NOT NULL CHECK(extraction_status IN ('machine_extracted','validated','human_reviewed','blocked')),exception_reason TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(production_run_id,fiscal_year,segment_type,segment_key,metric_key));
CREATE INDEX IF NOT EXISTS financial_segment_facts_company_year_idx ON research.financial_segment_facts(company_id,fiscal_year DESC,segment_type);
CREATE TABLE IF NOT EXISTS research.financial_history_gaps (id BIGSERIAL PRIMARY KEY,company_id BIGINT NOT NULL REFERENCES research.companies(id),section_key TEXT NOT NULL,metric_key TEXT NOT NULL,period_start DATE,period_end DATE,gap_status TEXT NOT NULL CHECK(gap_status IN ('missing','blocked','not_comparable','not_disclosed')),reason TEXT NOT NULL,next_source TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(company_id,section_key,metric_key,period_start,period_end));
COMMIT;
